// Computes S(n) = 1 + 2 + ... + n for n given as u64.
//
// Assumption from the problem statement: S(n) < 10_000, so the result fits
// comfortably in u64 and no overflow occurs.

pub fn compute_arith_sum(n: u64) -> u64 {
    let mut idx: u64 = 0;
    let mut sum: u64 = 0;

    // Loop invariant (informal):
    // - 0 <= idx <= n
    // - sum == 1 + 2 + ... + idx
    while idx < n {
        idx += 1;
        // sum becomes (1 + ... + (idx-1)) + idx == 1 + ... + idx
        sum += idx;
    }

    sum
}